#!/bin/bash
#
set -o xtrace

/usr/bin/drop_caches

declare -a leaf_wrap_seq=(2 4 8 16 32 64 128 256 512 1024)
# declare -a leaf_wrap_seq=(64)

Nodes=(1000000000)
Dim=(1)
tag=$((2#11100000))
summary=0
query_type=$((2#0))
instance_n=1
round=3

log_path="logs/incremental_updates_new"
mkdir -p "${log_path}"

# NOTE: the incremental-update root, generated by gen_incre_data.sh.  Tags 1<<6
# and 1<<7 need batches that were laid out for the ratio they slice at; the
# standard /data/zmen002/kv_pair datasets are globally shuffled, so every batch
# there comes out uniform no matter what <dis> says.  Both roots have the same
# ins/<ratio>/ and del/<ratio>/ directories, so pointing this at the old one
# still RUNS -- it just silently measures the old data.
data_prefix="/data/zmen002/kv_pair_incre"
# data_prefix="/data/zmen002/kv_pair"
batch_op_seq=("ins")
dis_seq=("uni" "norm" "seg")
# NOTE: -b only picks the file handed to -p (tag 1<<5's static-build control).
# Tags 1<<6 / 1<<7 ignore it and walk incre_ratio_seq in test_framework.h,
# reloading ins/<1/ratio>/ and del/<1/ratio>/ per ratio.  1/0.01 = 100, which is
# a directory gen_incre_data.sh writes.
batch_ratio="0.01"

function run_test() {
	local leaf_idx="$1"
	local solver="$2"
	local tree="$3"

	local exe="../build/${solver}"

	for dim in "${Dim[@]}"; do
		for dis in "${dis_seq[@]}"; do
			for batch_op in "${batch_op_seq[@]}"; do
				for node in "${Nodes[@]}"; do

					local x=$(bc <<<"scale=0; 1/$batch_ratio") || return 1
					local file_prefix="${data_prefix}/${dis}/${node}_${dim}/${batch_op}/${x}"

					local dest="${log_path}/${tree}/${dis}/${leaf_wrap_seq[${leaf_idx}]}.log"
					mkdir -p "${dest%/*}"
					: >"${dest}"
					echo ">>>${dest}"

					for ((j = 1; j <= instance_n; j++)); do
						numactl -i all "${exe}" -p "${file_prefix}/${j}.batch.bin" -r "${round}" -s ${summary} -t ${tag} -q ${query_type} -b "${batch_ratio}" -T "${tree}" -D "${dis}" 2>&1 | tee -a "${dest}"
					done
				done
			done
		done
	done
}

function run_cmake() {
	/usr/bin/drop_caches
	local leaf_idx="$1"
	local solver="$2"

	local cur_path
	cur_path=$(pwd)
	cd ../build || exit
	rm -rf *
	cmake -DDEBUG=OFF -DCMAKE_CXX_COMPILER=g++ -DOSM=OFF -DDYNAMIC_GRAPH=OFF -DJEMA=ON -DLEAF="${leaf_wrap_seq[${leaf_idx}]}" "${HOME}/ParallelMultiwayOrderedSet"
	make "${solver}" -j
	cd "${cur_path}" || exit
}

# # PMA
# tree=3
# solver="pma"
# run_cmake 0 "${solver}"
# run_test 0 "${solver}" "${tree}"

# # PAM
# tree=2
# solver="cpam"
# run_cmake 0 "${solver}"
# run_test 0 "${solver}" "${tree}"

# # CPAM
# tree=1
# solver="cpam"
# run_cmake 0 "${solver}"
# run_test 0 "${solver}" "${tree}"

# ours
solver="b_test"
tree=0
for idx in "${!leaf_wrap_seq[@]}"; do
	run_cmake "${idx}" "${solver}"
	run_test "${idx}" "${solver}" "${tree}"
done

